private val Cream=Color(0xFFF7F2E9);private val Ink=Color(0xFF211B18);private val Coffee=Color(0xFF65422F);private val Tint=Color(0xFFE9E2EA)
private fun money(v:Long)="%,dđ".format(v).replace(',','.');private fun clock(v:Long)=SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(v))
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);enableEdgeToEdge();setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Coffee,background=Cream,surface=Color(0xFFFFFCF7),onSurface=Ink)){Surface(Modifier.fillMaxSize().safeDrawingPadding(),color=Cream){App()}}}}}
@Composable private fun App(vm:PosViewModel=viewModel()){val sc by vm.screen.collectAsState();val t by vm.currentTable.collectAsState();val s by vm.currentSession.collectAsState();when(sc){"TABLES"->Tables(vm);"ORDER"->t?.let{Order(vm,it)};"SENT"->if(t!=null&&s!=null)Sent(vm,t!!,s!!);"PAY"->if(t!=null&&s!=null)Pay(vm,t!!,s!!);"HISTORY"->History(vm);"REPORT"->Report(vm);"MANAGE"->Manage(vm);"MENU"->MenuManager(vm);"EMP"->EmployeeManager(vm);"PURCHASE"->PurchaseManager(vm);"SETTINGS"->Settings(vm)}}
@Composable private fun Brand(title:String="",back:(()->Unit)?=null,manage:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(18.dp),verticalAlignment=Alignment.CenterVertically){if(back==null)Column{Text("0210",fontSize=32.sp,fontWeight=FontWeight.Black);Text("BREAKFAST · COFFEE · DRINKS",fontSize=9.sp)}else Text("‹",Modifier.clickable{back()}.padding(6.dp),fontSize=36.sp);Spacer(Modifier.weight(1f));if(title.isNotEmpty())Text(title,fontSize=21.sp,fontWeight=FontWeight.Bold);if(manage!=null)Text("☰",Modifier.clickable{manage()}.padding(12.dp),fontSize=25.sp)}}
@Composable private fun Tables(vm:PosViewModel){val areas by vm.areas.collectAsState();val tables by vm.tables.collectAsState();val sessions by vm.sessions.collectAsState();val emps by vm.employees.collectAsState();var area by remember{mutableStateOf("inside")};val employee=emps.firstOrNull{it.active}?.id?:"e0";Column{Brand(manage={vm.screen.value="MANAGE"});Row(Modifier.padding(horizontal=12.dp)){TextButton({}){Text("BÁN HÀNG",fontWeight=FontWeight.Bold)};TextButton({vm.screen.value="HISTORY"}){Text("LỊCH SỬ")};TextButton({vm.screen.value="REPORT"}){Text("BÁO CÁO")}};Row(Modifier.padding(horizontal=16.dp)){areas.forEach{a->FilterChip(area==a.id,{area=a.id},{Text(a.name)},Modifier.padding(end=8.dp))}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(tables.filter{it.areaId==area}.chunked(2)){r->Row{r.forEach{tb->val ss=sessions.firstOrNull{it.tableId==tb.id};Card(Modifier.weight(1f).height(116.dp).padding(5.dp).clickable{vm.selectTable(tb,employee)},shape=RoundedCornerShape(14.dp),colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.fillMaxSize(),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text(tb.name,fontWeight=FontWeight.Bold,fontSize=18.sp);Text(if(ss==null)"Trống" else "Đang phục vụ · ${clock(ss.openedAt)}",fontSize=12.sp,color=Coffee)}}};if(r.size==1)Spacer(Modifier.weight(1f))}}};Button({vm.addTable(area)},Modifier.fillMaxWidth().padding(16.dp).height(54.dp)){Text("＋ TẠO BÀN")}}}
@Composable private fun Staff(es:List<EmployeeEntity>,sel:String,set:(String)->Unit,label:String){var x by remember{mutableStateOf(false)};Box{OutlinedButton({x=true}){Text("$label: ${es.firstOrNull{it.id==sel}?.name?:"--"} ▾")};DropdownMenu(x,{x=false}){es.filter{it.active}.forEach{e->DropdownMenuItem({Text(e.name)},{set(e.id);x=false})}}}}
@Composable private fun Order(vm:PosViewModel,t:DiningTableEntity){val cats by vm.categories.collectAsState();val menu by vm.menu.collectAsState();val es by vm.employees.collectAsState();val cart by vm.cart.collectAsState();var cat by remember(cats){mutableStateOf(cats.firstOrNull()?.id?:"")};var emp by remember(es){mutableStateOf(es.firstOrNull{it.active}?.id?:"")};val total=cart.entries.sumOf{(id,q)->(menu.firstOrNull{it.id==id}?.price?:0)*q};Column{Brand(t.name,{vm.screen.value="TABLES"});LazyColumn(Modifier.weight(1f).padding(12.dp)){item{LazyRowLike(cats,cat){cat=it};Staff(es,emp,{emp=it},"NV order")};items(menu.filter{it.categoryId==cat&&it.active}){m->val q=cart[m.id]?:0;Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(m.name,fontWeight=FontWeight.Bold);Text(money(m.price))};if(q>0){Text("−",Modifier.clickable{vm.sub(m)}.padding(12.dp));Text("$q")};Text("＋",Modifier.clickable{vm.add(m)}.padding(12.dp),fontSize=22.sp)}}}};Text("${cart.values.sum()} món · ${money(total)}",Modifier.padding(horizontal=18.dp),fontWeight=FontWeight.Bold);Button({vm.sendBatch(emp)},enabled=cart.isNotEmpty(),modifier=Modifier.fillMaxWidth().padding(16.dp).height(56.dp)){Text("GỬI LÀM HÀNG")}}}
@Composable private fun LazyRowLike(cats:List<MenuCategoryEntity>,sel:String,set:(String)->Unit){Row{cats.take(4).forEach{c->FilterChip(sel==c.id,{set(c.id)},{Text(c.name)},Modifier.padding(3.dp))}}}
@Composable private fun Sent(vm:PosViewModel,t:DiningTableEntity,s:TableSessionEntity){val bs by vm.batches(s.id).collectAsState(initial=emptyList());val total by vm.total(s.id).collectAsState(initial=0);val es by vm.employees.collectAsState();Column{Brand(t.name,{vm.screen.value="TABLES"});Text("ĐÃ GỌI",Modifier.padding(horizontal=18.dp),fontSize=20.sp,fontWeight=FontWeight.Bold);LazyColumn(Modifier.weight(1f).padding(12.dp)){items(bs){b->val its by vm.items(b.id).collectAsState(initial=emptyList());Card(Modifier.fillMaxWidth().padding(5.dp),colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(14.dp)){Text("${clock(b.sentAt?:b.createdAt)} · Đơn #${b.sequence.toString().padStart(3,'0')}",fontWeight=FontWeight.Bold);Text("● Đã gửi làm hàng · ${es.firstOrNull{it.id==b.ordererId}?.name?:"NV"}",color=Color(0xFF43835E),fontSize=12.sp);its.forEach{i->Text("${i.qty} × ${i.itemNameSnapshot}${if(i.note.isBlank())"" else " · ${i.note}"}",Modifier.padding(top=7.dp))}}}}};Text("Tạm tính ${money(total)}",Modifier.padding(horizontal=18.dp),fontWeight=FontWeight.Bold);Row(Modifier.padding(16.dp)){OutlinedButton({vm.screen.value="ORDER"},Modifier.weight(1f)){Text("＋ GỌI THÊM")};Spacer(Modifier.width(8.dp));Button({vm.screen.value="PAY"},Modifier.weight(1f),enabled=bs.isNotEmpty()){Text("THANH TOÁN")}}}}
@Composable private fun Pay(vm:PosViewModel,t:DiningTableEntity,s:TableSessionEntity){val total by vm.total(s.id).collectAsState(initial=0);val es by vm.employees.collectAsState();var cashier by remember(es){mutableStateOf(es.firstOrNull{it.active}?.id?:"")};var method by remember{mutableStateOf("CASH")};Column{Brand("Thanh toán",{vm.screen.value="SENT"});Column(Modifier.weight(1f).padding(18.dp)){Text("${t.name} · Mở ${clock(s.openedAt)}",fontWeight=FontWeight.Bold);Spacer(Modifier.height(18.dp));Text("TỔNG CỘNG");Text(money(total),fontSize=36.sp,fontWeight=FontWeight.Black);Row{FilterChip(method=="CASH",{method="CASH"},{Text("TIỀN MẶT")});Spacer(Modifier.width(8.dp));FilterChip(method=="TRANSFER",{method="TRANSFER"},{Text("CHUYỂN KHOẢN")})};Spacer(Modifier.height(14.dp));Staff(es,cashier,{cashier=it},"Người thu tiền");if(method=="TRANSFER"){Spacer(Modifier.height(18.dp));Card(colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(18.dp)){Text("VIETQR",fontWeight=FontWeight.Black,fontSize=20.sp);Text("QR ngân hàng sẽ lấy từ Cài đặt VietQR");Text("Số tiền: ${money(total)}");Text("Nội dung: 0210 ${t.name}")}}}};Button({vm.close(method,cashier,total)},Modifier.fillMaxWidth().padding(18.dp).height(58.dp),enabled=total>0){Text("✓ XÁC NHẬN THANH TOÁN")}}}
@Composable private fun History(vm:PosViewModel){val bills by vm.bills.collectAsState();Column{Brand("Lịch sử",{vm.screen.value="TABLES"});LazyColumn(Modifier.padding(14.dp)){item{Text("BILL ĐÃ ĐÓNG",fontWeight=FontWeight.Bold)};items(bills){b->Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Row(Modifier.padding(14.dp)){Column(Modifier.weight(1f)){Text(b.billNo,fontWeight=FontWeight.Bold);Text("${b.closedAt?.let{clock(it)}?:""} · ${((b.closedAt?:b.openedAt)-b.openedAt)/60000} phút")};Text(money(b.total),fontWeight=FontWeight.Bold)}}}}}}
@Composable private fun Report(vm:PosViewModel){val bills by vm.bills.collectAsState();val ps by vm.purchases.collectAsState();val pays by vm.payments.collectAsState();val rev=bills.sumOf{it.total};val input=ps.sumOf{it.total};val cash=pays.filter{it.method=="CASH"}.sumOf{it.amount};Column{Brand("Báo cáo",{vm.screen.value="TABLES"});LazyColumn(Modifier.padding(16.dp)){item{Metric("DOANH THU",rev);Row{Text("Tiền mặt ${money(cash)}",Modifier.weight(1f));Text("Chuyển khoản ${money(rev-cash)}")};Spacer(Modifier.height(12.dp));Metric("NHẬP ĐẦU VÀO",input);Metric("CHÊNH LỆCH THU - NHẬP",rev-input);Text("${bills.size} bill đã đóng · dữ liệu Room",Modifier.padding(top=12.dp))}}}}
@Composable private fun Metric(n:String,v:Long){Card(Modifier.fillMaxWidth().padding(vertical=5.dp),colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(18.dp)){Text(n,fontSize=12.sp);Text(money(v),fontSize=27.sp,fontWeight=FontWeight.Black)}}}
@Composable private fun Manage(vm:PosViewModel){Column{Brand("Quản lý",{vm.screen.value="TABLES"});LazyColumn(Modifier.padding(16.dp)){item{Text("VẬN HÀNH",fontWeight=FontWeight.Bold);ManageRow("☕","Menu","Món bán · giá · nhóm món"){vm.screen.value="MENU"};ManageRow("▦","Bàn & khu vực","Trong nhà · Ngoài trời"){vm.screen.value="TABLES"};ManageRow("♙","Nhân viên","Order · thu tiền"){vm.screen.value="EMP"};ManageRow("↓","Nhập đầu vào","Phiếu nhập · nhà cung cấp"){vm.screen.value="PURCHASE"};Spacer(Modifier.height(18.dp));Text("THIẾT BỊ & HỆ THỐNG",fontWeight=FontWeight.Bold);ManageRow("▣","Máy in","Phiếu làm hàng · in lại"){vm.screen.value="SETTINGS"};ManageRow("QR","VietQR","Tài khoản nhận tiền"){vm.screen.value="SETTINGS"};ManageRow("⚙","Cài đặt / Sao lưu","Thiết bị · dữ liệu"){vm.screen.value="SETTINGS"}}}}}
@Composable private fun ManageRow(icon:String,title:String,sub:String,go:()->Unit){Card(Modifier.fillMaxWidth().padding(vertical=5.dp).clickable{go()}){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text(icon,fontSize=22.sp,modifier=Modifier.width(40.dp));Column(Modifier.weight(1f)){Text(title,fontWeight=FontWeight.Bold);Text(sub,fontSize=12.sp,color=Coffee)};Text("›",fontSize=25.sp)}}}
@Composable private fun MenuManager(vm:PosViewModel){val menu by vm.menu.collectAsState();val cats by vm.categories.collectAsState();var add by remember{mutableStateOf(false)};Column{Brand("Menu",{vm.screen.value="MANAGE"});Row(Modifier.padding(horizontal=16.dp)){Text("${menu.count{it.active}} món đang bán",Modifier.weight(1f));Button({add=true}){Text("＋ THÊM MÓN")}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(menu){m->Card(Modifier.fillMaxWidth().padding(4.dp)){Row(Modifier.padding(13.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(m.name,fontWeight=FontWeight.Bold);Text("${cats.firstOrNull{it.id==m.categoryId}?.name} · ${money(m.price)}",fontSize=12.sp)};Switch(m.active,{vm.toggleMenu(m)})}}}}};if(add)AddMenuDialog(vm,cats){add=false}}
@Composable private fun AddMenuDialog(vm:PosViewModel,cats:List<MenuCategoryEntity>,close:()->Unit){var name by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var cat by remember{mutableStateOf(cats.firstOrNull()?.id?:"")};AlertDialog(close,{Button({vm.saveMenu(name,price.toLongOrNull()?:0,cat);close()},enabled=name.isNotBlank()&&price.toLongOrNull()!=null){Text("LƯU")}},dismissButton={TextButton(close){Text("HỦY")}},title={Text("Thêm món")},text={Column{OutlinedTextField(name,{name=it},label={Text("Tên món")});OutlinedTextField(price,{price=it.filter(Char::isDigit)},label={Text("Giá bán")});cats.forEach{c->FilterChip(cat==c.id,{cat=c.id},{Text(c.name)},Modifier.padding(2.dp))}}})}
@Composable private fun EmployeeManager(vm:PosViewModel){val es by vm.employees.collectAsState();var name by remember{mutableStateOf("")};Column{Brand("Nhân viên",{vm.screen.value="MANAGE"});Row(Modifier.padding(16.dp)){OutlinedTextField(name,{name=it},Modifier.weight(1f),label={Text("Tên nhân viên")});Button({vm.saveEmployee(name);name=""},enabled=name.isNotBlank(),modifier=Modifier.padding(start=8.dp)){Text("THÊM")}};LazyColumn(Modifier.padding(12.dp)){items(es){e->Card(Modifier.fillMaxWidth().padding(4.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Text(e.name,Modifier.weight(1f),fontWeight=FontWeight.Bold);Switch(e.active,{vm.toggleEmployee(e)})}}}}}}
